// Homework tracker — Cloudflare Worker + KV (multi-week model).
// KV keys:
//   week:<week name> -> {week, updated, tasks: [...]}
//   meta             -> {weeks: [...chronological...], current: "<week name>"}
// Legacy key "state" (single-week doc from the first deployment) is merged
// once, when its week is synced, then deleted.
// Task flags, computed at sync time:
//   carried — the task (same child + title) was in the previous week's list
//   is_new  — it was not (added this week)
//   done    — sheet "בוצע" OR the site's own checkmark (preserved per week,
//             and carried forward for carried tasks)
// Routes: GET / (page), GET /api/weeks, GET /api/tasks[?week=],
// POST /api/tasks/:id/done[?week=],
// POST /api/sync (Bearer SYNC_SECRET — upserts one week, keeps meta current).
//
// NOTE: D1 was not available — the API token has no D1 scope (401 on every
// D1 call). KV covers this app fully: small documents, read often, written
// rarely. KV reads are eventually consistent (a fresh write can take up to
// ~20s to show from another edge location).

const HTML = "<!DOCTYPE html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>שיעורי בית — דניאל ונאיה</title>\n<style>\n  :root{\n    --bg:#fdf6ec; --card:#fffdf8; --ink:#2e2a25; --muted:#8a7d6d;\n    --accent:#d97757; --accent-soft:#fdeee6;\n    --daniel:#2563eb; --daniel-soft:#dbeafe;\n    --naya:#db2777; --naya-soft:#fce7f3;\n    --green:#16a34a; --green-soft:#dcfce7;\n    --amber:#b45309; --amber-soft:#fef3c7;\n    --red:#dc2626; --red-soft:#fee2e2;\n    --line:#f0e3d3; --radius:20px;\n  }\n  *{box-sizing:border-box}\n  body{\n    margin:0; background:var(--bg); color:var(--ink);\n    font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Arial,sans-serif;\n    -webkit-tap-highlight-color:transparent;\n  }\n  .wrap{max-width:720px; margin:0 auto; padding:18px 14px 48px}\n  header{margin:4px 4px 12px}\n  h1{font-size:28px; margin:0 0 4px}\n  .sub{color:var(--muted); font-size:14px}\n  .syncrow{display:flex; align-items:center; gap:10px; margin:12px 4px 0}\n  .syncbtn{\n    flex:none; border:1.5px solid var(--line); background:var(--card); color:var(--ink);\n    border-radius:999px; padding:8px 16px; font-size:14px; font-weight:700; cursor:pointer;\n    box-shadow:0 2px 8px rgba(93,64,28,.06);\n  }\n  .syncbtn:disabled{opacity:.6; cursor:default}\n  .syncbtn:active{background:var(--accent-soft)}\n  .syncstatus{font-size:13px; color:var(--muted)}\n  .updated{font-size:14px; font-weight:700; margin-top:6px}\n  .sources{font-size:13px; color:var(--muted); margin-top:4px}\n\n  /* ---- week navigator ---- */\n  .weeknav{\n    background:var(--card); border:1px solid var(--line); border-radius:var(--radius);\n    padding:12px 10px; margin:12px 0 10px; box-shadow:0 1px 2px rgba(0,0,0,.04);\n  }\n  .weeknav-row{display:flex; align-items:center; gap:6px}\n  .navbtn{\n    flex:none; width:38px; height:38px; border-radius:50%;\n    border:1.5px solid var(--line); background:#fff; font-size:18px; cursor:pointer;\n    color:var(--ink); line-height:1;\n  }\n  .navbtn:disabled{opacity:.3; cursor:default}\n  .weeklabel{flex:1; text-align:center; min-width:0}\n  .weeklabel .wname{font-size:18px; font-weight:800}\n  .weeklabel .wtag{\n    display:inline-block; font-size:11px; font-weight:700; color:var(--green);\n    background:var(--green-soft); border-radius:999px; padding:2px 8px; margin-inline-start:6px;\n    vertical-align:2px;\n  }\n  .weeklabel .wtag.old{color:var(--muted); background:#f3f4f6}\n  .weekchips{\n    display:flex; gap:6px; overflow-x:auto; padding:10px 2px 2px;\n    scrollbar-width:none;\n  }\n  .weekchips::-webkit-scrollbar{display:none}\n  .wchip{\n    flex:none; border:1.5px solid var(--line); background:#fff; color:var(--ink);\n    border-radius:999px; padding:6px 12px; font-size:13px; cursor:pointer; font-weight:600;\n  }\n  .wchip.on{border-color:var(--accent); background:var(--accent); color:#fff}\n  .weekstats{\n    display:flex; flex-wrap:wrap; gap:6px 14px; margin:2px 4px 4px;\n    font-size:13px; color:var(--muted);\n  }\n  .weekstats b{color:var(--ink)}\n  .weekstats .st-new{color:#15803d; font-weight:700}\n  .weekstats .st-carried{color:var(--amber); font-weight:700}\n\n  .filters{display:flex; flex-wrap:wrap; gap:8px; margin:12px 4px}\n  .chip{\n    border:1.5px solid var(--line); background:#fff; color:var(--ink);\n    border-radius:999px; padding:8px 14px; font-size:14px; cursor:pointer;\n  }\n  .chip.on{border-color:var(--accent); background:var(--accent); color:#fff}\n  .chip.daniel.on{border-color:var(--daniel); background:var(--daniel)}\n  .chip.naya.on{border-color:var(--naya); background:var(--naya)}\n\n  .child{margin-top:18px}\n  .child-head{display:flex; align-items:baseline; gap:10px; padding:0 4px 8px}\n  .dot{width:14px; height:14px; border-radius:50%; flex:none; transform:translateY(1px)}\n  .dot.daniel{background:var(--daniel)} .dot.naya{background:var(--naya)}\n  .child-head h2{font-size:20px; margin:0}\n  .count{color:var(--muted); font-size:13px; margin-inline-start:auto}\n  .bar{height:8px; background:#e7e2d9; border-radius:99px; overflow:hidden; margin:0 4px 10px}\n  .bar > div{height:100%; border-radius:99px; transition:width .3s}\n  .bar.daniel > div{background:var(--daniel)}\n  .bar.naya > div{background:var(--naya)}\n\n  .card{\n    background:var(--card); border:1px solid var(--line); border-radius:var(--radius);\n    padding:14px 14px 0; margin-bottom:10px;\n    box-shadow:0 2px 10px rgba(93,64,28,.05);\n  }\n  .card.done{opacity:.62}\n  .card.done .title{text-decoration:line-through}\n  .card-top{display:flex; gap:12px; align-items:flex-start}\n  .check{\n    flex:none; width:30px; height:30px; margin-top:2px; cursor:pointer;\n    accent-color:var(--green); transform:scale(1.25);\n  }\n  .card-main{flex:1; min-width:0}\n  .title-row{display:flex; align-items:flex-start; gap:10px; flex-wrap:wrap}\n  .title{font-size:17px; font-weight:700; line-height:1.4; flex:1; min-width:140px}\n  .duepill{\n    flex:none; font-size:14px; font-weight:800; border-radius:999px;\n    padding:5px 12px; white-space:nowrap;\n    background:#f3f4f6; color:var(--muted);\n  }\n  .duepill.today{background:var(--red-soft); color:var(--red)}\n  .duepill.tomorrow{background:var(--amber-soft); color:var(--amber)}\n  .duepill.overdue{background:var(--red-soft); color:var(--red)}\n  .duepill.future{background:var(--daniel-soft); color:var(--daniel)}\n  .duepill.given{background:#f3f4f6; color:var(--muted)}\n  .tags{display:flex; flex-wrap:wrap; gap:6px; margin-top:8px}\n  .tag{\n    font-size:12px; font-weight:700; border-radius:999px; padding:3px 9px;\n    background:#f3f4f6; color:var(--muted);\n  }\n  .tag.carried{background:var(--amber-soft); color:var(--amber)}\n  .tag.isnew{background:var(--green-soft); color:#15803d}\n  .details-btn{\n    display:block; width:100%; margin-top:10px; padding:10px 4px;\n    border:none; border-top:1px solid var(--line); background:none;\n    color:var(--daniel); font-size:14px; font-weight:700; cursor:pointer;\n    text-align:center;\n  }\n  .details{display:none; padding:0 0 14px}\n  .details.open{display:block}\n  .details-text{font-size:15px; line-height:1.65; margin:4px 0 8px}\n  .details-meta{color:var(--muted); font-size:13px; line-height:1.6}\n  .links{display:flex; flex-wrap:wrap; gap:6px; margin-top:10px}\n  .links a{\n    font-size:13px; color:var(--daniel); background:var(--daniel-soft);\n    border-radius:999px; padding:5px 11px; text-decoration:none; font-weight:600;\n  }\n  .empty{\n    text-align:center; color:var(--muted); padding:28px 10px; font-size:15px;\n    background:var(--card); border:1px dashed var(--line); border-radius:var(--radius);\n  }\n  .alldone{\n    text-align:center; padding:22px 10px; font-size:18px; font-weight:700;\n    background:var(--green-soft); color:var(--green);\n    border-radius:var(--radius); margin-top:6px;\n  }\n  footer{color:var(--muted); font-size:12px; text-align:center; margin-top:26px; line-height:1.7}\n  .err{\n    display:none; background:var(--red-soft); color:var(--red); border-radius:12px;\n    padding:12px; margin:10px 4px; font-size:14px; text-align:center;\n  }\n\n  /* ---- tabs ---- */\n  .tabs{display:flex; gap:8px; margin:12px 4px 4px}\n  .tab{flex:1; border:1.5px solid var(--line); background:var(--card); color:var(--ink); border-radius:999px; padding:10px 6px; font-size:14px; font-weight:700; cursor:pointer}\n  .tab.on{border-color:var(--accent); background:var(--accent); color:#fff}\n  .daychips{display:flex; gap:6px; overflow-x:auto; padding:10px 2px 2px; scrollbar-width:none; margin:8px 4px}\n  .daychips::-webkit-scrollbar{display:none}\n  .dchip{flex:none; border:1.5px solid var(--line); background:#fff; color:var(--ink); border-radius:999px; padding:6px 12px; font-size:13px; cursor:pointer; font-weight:600}\n  .dchip.on{border-color:var(--accent); background:var(--accent); color:#fff}\n  .dchip.today{border-color:var(--daniel)}\n  .sched-day{font-size:18px; font-weight:800; margin:14px 4px 4px}\n  .sched-day .today-tag{font-size:11px; font-weight:700; color:var(--green); background:var(--green-soft); border-radius:999px; padding:2px 8px; margin-inline-start:6px; vertical-align:2px}\n  .srow{display:flex; gap:10px; align-items:baseline; background:var(--card); border:1px solid var(--line); border-radius:12px; padding:10px 12px; margin-bottom:6px}\n  .srow .stime{flex:none; font-weight:700; font-variant-numeric:tabular-nums; direction:ltr; min-width:108px}\n  .srow .stitle{flex:1; font-weight:600}\n  .srow .stag{flex:none; font-size:11px; font-weight:700; border-radius:999px; padding:2px 8px}\n  .stag.school{background:var(--daniel-soft); color:#1e40af}\n  .stag.tzaharon{background:var(--green-soft); color:#166534}\n  .stag.chug{background:var(--naya-soft); color:#9d174d}\n  .stag.end{background:#f3f4f6; color:var(--muted)}\n  .srow.now{border-color:var(--green); box-shadow:0 0 0 1px var(--green)}\n  .srow .nowtag{color:var(--green); font-size:11px; font-weight:800}\n  .srow.tzbar{background:var(--green-soft); border-color:#bbf7d0; color:#166534; font-weight:700}\n  .srow.brk{background:#fafaf9; border:1px dashed var(--line)}\n  .srow.brk .stitle{color:var(--muted)}\n  .stag.brk{background:#f3f4f6; color:var(--muted)}\n  .sched-note{font-size:12px; color:var(--muted); margin:14px 4px; line-height:1.6}\n  .sharebtn{display:block; width:calc(100% - 8px); margin:10px 4px; padding:11px; border:1.5px solid var(--line); background:#fff; border-radius:999px; font-size:14px; font-weight:700; cursor:pointer; color:var(--ink)}\n  .sharebtn:active{background:#f3f4f6}\n\n  /* ---- reminders ---- */\n  .rem-date-row{display:flex; gap:8px; align-items:center; margin:10px 4px}\n  .rem-date-row input[type=\"date\"]{\n    flex:1; border:1.5px solid var(--line); background:var(--card); color:var(--ink);\n    border-radius:12px; padding:9px 10px; font-size:15px; font-family:inherit;\n  }\n  .rem-today{flex:none; border:1.5px solid var(--line); background:var(--card); color:var(--ink); border-radius:999px; padding:8px 14px; font-size:13px; font-weight:700; cursor:pointer}\n  .rem-form{\n    background:var(--card); border:1px solid var(--line); border-radius:var(--radius);\n    padding:14px; margin:10px 4px; box-shadow:0 2px 10px rgba(93,64,28,.05);\n  }\n  .rem-form input[type=\"text\"]{\n    width:100%; border:1.5px solid var(--line); background:#fff; color:var(--ink);\n    border-radius:12px; padding:11px 12px; font-size:16px; font-family:inherit; margin-bottom:8px;\n  }\n  .rem-form-row{display:flex; gap:8px}\n  .rem-form-row input[type=\"time\"], .rem-form-row select{\n    flex:1; min-width:0; border:1.5px solid var(--line); background:#fff; color:var(--ink);\n    border-radius:12px; padding:9px 10px; font-size:14px; font-family:inherit;\n  }\n  .rem-add{\n    width:100%; margin-top:10px; border:none; background:var(--accent); color:#fff;\n    border-radius:999px; padding:12px; font-size:15px; font-weight:800; cursor:pointer;\n  }\n  .rem-add:disabled{opacity:.6}\n  .rem-sec{font-size:16px; font-weight:800; margin:18px 4px 6px}\n  .rem-row{display:flex; gap:10px; align-items:flex-start; background:var(--card); border:1px solid var(--line); border-radius:14px; padding:11px 12px; margin:0 4px 6px}\n  .rem-row.done{opacity:.6}\n  .rem-row.done .rem-text{text-decoration:line-through}\n  .rem-check{flex:none; width:26px; height:26px; margin-top:1px; cursor:pointer; accent-color:var(--green); transform:scale(1.2)}\n  .rem-main{flex:1; min-width:0}\n  .rem-text{font-weight:700; font-size:15px; line-height:1.4}\n  .rem-meta{font-size:13px; color:var(--muted); margin-top:3px}\n  .rem-del{flex:none; border:none; background:none; color:var(--muted); font-size:16px; cursor:pointer; padding:2px 6px}\n  .rem-empty{text-align:center; color:var(--muted); padding:20px 10px; font-size:14px; background:var(--card); border:1px dashed var(--line); border-radius:var(--radius); margin:0 4px}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <h1>📚 דניאל ונאיה</h1>\n    <div class=\"sub\">שיעורי בית, מערכת שעות ותזכורות — הכל במקום אחד 🌼</div>\n    <div class=\"syncrow\">\n      <button class=\"syncbtn\" id=\"syncBtn\">🔄 סנכרן</button>\n      <span class=\"syncstatus\" id=\"syncStatus\"></span>\n    </div>\n  </header>\n\n  <nav class=\"tabs\">\n    <button class=\"tab on\" data-tab=\"homework\">📚 שיעורי בית</button>\n    <button class=\"tab\" data-tab=\"schedule\">🗓️ מערכת שעות</button>\n    <button class=\"tab\" data-tab=\"reminders\">⏰ תזכורות</button>\n  </nav>\n\n  <div class=\"err\" id=\"err\">לא הצלחתי לטעון את המשימות — נסו לרענן את הדף.</div>\n\n  <div id=\"homeworkView\">\n    <div class=\"updated\" id=\"lastUpdated\"></div>\n    <div class=\"sources\" id=\"sourcePulls\"></div>\n\n  <div class=\"weeknav\" id=\"weeknav\" style=\"display:none\">\n    <div class=\"weeknav-row\">\n      <button class=\"navbtn\" id=\"prevWeek\" aria-label=\"שבוע קודם\">›</button>\n      <div class=\"weeklabel\">\n        <span class=\"wname\" id=\"weekName\"></span><span class=\"wtag\" id=\"weekTag\"></span>\n      </div>\n      <button class=\"navbtn\" id=\"nextWeek\" aria-label=\"שבוע הבא\">‹</button>\n    </div>\n    <div class=\"weekchips\" id=\"weekChips\"></div>\n  </div>\n  <div class=\"weekstats\" id=\"weekStats\"></div>\n\n  <div class=\"filters\" id=\"statusFilters\">\n    <button class=\"chip\" data-status=\"all\">הכל</button>\n    <button class=\"chip on\" data-status=\"open\">פתוחות</button>\n    <button class=\"chip\" data-status=\"done\">בוצעו</button>\n  </div>\n  <div class=\"filters\" id=\"childFilters\" style=\"margin-top:-6px\">\n    <button class=\"chip on\" data-child=\"all\">שני הילדים</button>\n    <button class=\"chip daniel\" data-child=\"daniel\">🔵 דניאל</button>\n    <button class=\"chip naya\" data-child=\"naya\">🩷 נאיה</button>\n  </div>\n\n  <div id=\"app\"></div>\n  </div>\n\n  <div id=\"scheduleView\" style=\"display:none\">\n    <div class=\"daychips\" id=\"dayChips\"></div>\n    <button class=\"sharebtn\" id=\"shareSched\">🔗 העתק קישור ליום הזה</button>\n    <div id=\"schedApp\"></div>\n    <div class=\"sched-note\">שעות השיעורים של נאיה לפי פעמוני בית הספר (כמו ג׳3) — אושרו התחלה 8:00 וסיום 12:45, שישי 11:40. מקורות: מערכת ג׳3 (ליאור, 11/9) · מערכת א׳2 (מורן, 4/11) · מערכת חוגים א2 (17/11) · יומן חוגים.</div>\n  </div>\n\n  <div id=\"remindersView\" style=\"display:none\">\n    <div class=\"rem-date-row\">\n      <input type=\"date\" id=\"remDate\" aria-label=\"תאריך\">\n      <button class=\"rem-today\" id=\"remToday\">היום</button>\n    </div>\n    <div class=\"rem-form\">\n      <input type=\"text\" id=\"remText\" placeholder=\"מה להזכיר? למשל: להביא חולצת ספורט\" maxlength=\"200\">\n      <div class=\"rem-form-row\">\n        <input type=\"time\" id=\"remTime\" aria-label=\"שעה\">\n        <select id=\"remChild\" aria-label=\"למי\">\n          <option value=\"all\">שני הילדים</option>\n          <option value=\"daniel\">🔵 דניאל</option>\n          <option value=\"naya\">🩷 נאיה</option>\n        </select>\n      </div>\n      <button class=\"rem-add\" id=\"remAdd\">＋ הוסף תזכורת</button>\n    </div>\n    <div id=\"remApp\"></div>\n    <div class=\"sched-note\">התזכורות נשמרות באתר ומשותפות לשניכם — מה שאחד מוסיף, השני רואה. הן לא נכנסות לגיליון שיעורי הבית.</div>\n  </div>\n\n  <footer>\n    מקור המשימות: גיליון שיעורי הבית • הסימונים נשמרים ומסונכרנים בין כולם<br>\n    מערכת שעות: מערכות בית הספר והחוגים כפי שנמסרו • נבנה לשימוש המשפחה\n  </footer>\n</div>\n\n<script>\nconst KIDS = {\n  daniel: { name: \"דניאל\", emoji: \"🔵\", cls: \"daniel\" },\n  naya:   { name: \"נאיה\",  emoji: \"🩷\", cls: \"naya\" }\n};\nlet WEEKS = { weeks: [], current: \"\" };\nlet DATA = { week: \"\", updated: \"\", tasks: [] };\nlet viewWeek = \"\";\nlet statusFilter = \"open\";\nlet childFilter = \"all\";\n\n/* ---- reminders (shared, stored in KV via /api/reminders) ---- */\nlet REMINDERS = [];\nlet remDate = \"\"; // set to today on first render (todayISO is defined below)\nlet lastLoadAt = 0;\n\n/* ---- weekly timetable (static reference data, updated 17/11/2026) ----\n   Sources: Daniel g3 PDF (Lior, 11/9) · Naya a2 PDF (Moran, 4/11) ·\n   A2 chugim photo (17/11) · Google \"חוגים\" calendar.\n   Confirmed by Oren 17/11: school starts 08:00 for both; Daniel has no\n   tzaharon; Naya ends school 12:45 (Fri 11:40) and goes straight to\n   tzaharon until 16:30, chugim during it. Naya's lesson times follow the\n   school bells (same as g3) — only start/end are confirmed. */\nconst SCHEDULE = { days: [\n  { daniel: { end: \"12:45\", tzaharon: null,\n      school: [[\"08:00–08:50\",\"מדעים\"],[\"08:50–09:35\",\"חינוך גופני\"],[\"10:10–10:55\",\"מתמטיקה\"],[\"10:55–11:40\",\"עברית\"],[\"12:00–12:45\",\"מולדת\"]],\n      tzchug: [], extra: [[\"16:00–17:00\",\"אנגלית\"]] },\n    naya: { end: \"12:45\", tzaharon: \"12:45–16:30\",\n      school: [[\"08:00–08:50\",\"שפה\"],[\"08:50–09:35\",\"שפה\"],[\"10:10–10:55\",\"חינוך גופני\"],[\"10:55–11:40\",\"חשבון\"],[\"12:00–12:45\",\"ספרייה / גאומטריה\"]],\n      tzchug: [[\"13:30–14:30\",\"תכשיטנות (גלי אדלשטיין)\"]], extra: [] } },\n  { daniel: { end: \"12:45\", tzaharon: null,\n      school: [[\"08:00–08:50\",\"אנגלית\"],[\"08:50–09:35\",\"אנגלית\"],[\"10:10–10:55\",\"עברית\"],[\"10:55–11:40\",\"גאומטריה\"],[\"12:00–12:45\",\"עברית\"]],\n      tzchug: [], extra: [[\"16:45–17:30\",\"שחייה\"]] },\n    naya: { end: \"12:45\", tzaharon: \"12:45–16:30\",\n      school: [[\"08:00–08:50\",\"שפה\"],[\"08:50–09:35\",\"אנגלית\"],[\"10:10–10:55\",\"חינוך גופני\"],[\"10:55–11:40\",\"חשבון\"],[\"12:00–12:45\",\"חשבון\"]],\n      tzchug: [[\"15:00–16:30\",\"אומנות משולבת (שרה)\"]], extra: [[\"17:45–18:30\",\"התעמלות קרקע\"]] } },\n  { daniel: { end: \"13:30\", tzaharon: null,\n      school: [[\"08:00–08:50\",\"מתמטיקה\"],[\"08:50–09:35\",\"מתמטיקה\"],[\"10:10–10:55\",\"לשון\"],[\"10:55–11:40\",\"אמנות\"],[\"12:00–12:45\",\"מדעים\"],[\"12:45–13:30\",\"חינוך גופני\"]],\n      tzchug: [], extra: [[\"15:00–16:00\",\"שיעור פרטי חשבון\"]] },\n    naya: { end: \"12:45\", tzaharon: \"12:45–16:30\",\n      school: [[\"08:00–08:50\",\"אומנות\"],[\"08:50–09:35\",\"ספורט בזמר\"],[\"10:10–10:55\",\"מוסיקה\"],[\"10:55–11:40\",\"זהירות בדרכים\"],[\"12:00–12:45\",\"מדעים\"]],\n      tzchug: [[\"14:15–15:00\",\"קוסמות (גאיה סלם)\"]], extra: [] } },\n  { daniel: { end: \"12:45\", tzaharon: null,\n      school: [[\"08:00–08:50\",\"עברית / כלבנות\"],[\"08:50–09:35\",\"עברית / כלבנות\"],[\"10:10–10:55\",\"מדעים\"],[\"10:55–11:40\",\"אנגלית\"],[\"12:00–12:45\",\"אנגלית מדוברת\"]],\n      tzchug: [], extra: [[\"16:45–17:30\",\"שחייה\"]] },\n    naya: { end: \"12:45\", tzaharon: \"12:45–16:30\",\n      school: [[\"08:00–08:50\",\"חשבון\"],[\"08:50–09:35\",\"שפה\"],[\"10:10–10:55\",\"חשבון\"],[\"10:55–11:40\",\"כישורי חיים\"],[\"12:00–12:45\",\"מדעים\"]],\n      tzchug: [[\"13:30–14:15\",\"וטרינריה (יובל כהן)\"]], extra: [[\"16:30–17:30\",\"שחייה (עם בן)\"]] } },\n  { daniel: { end: \"13:30\", tzaharon: null,\n      school: [[\"08:00–08:50\",\"מתמטיקה\"],[\"08:50–09:35\",\"מתמטיקה\"],[\"10:10–10:55\",\"מולדת\"],[\"10:55–11:40\",\"תנ״ך\"],[\"12:00–12:45\",\"מפתח הלב\"],[\"12:45–13:30\",\"עברית\"]],\n      tzchug: [], extra: [[\"16:25–17:25\",\"נינג׳ה\"]] },\n    naya: { end: \"12:45\", tzaharon: \"12:45–16:30\",\n      school: [[\"08:00–08:50\",\"שפה\"],[\"08:50–09:35\",\"שפה\"],[\"10:10–10:55\",\"חשבון\"],[\"10:55–11:40\",\"שפה / יוגה\"],[\"12:00–12:45\",\"שפה / יוגה\"]],\n      tzchug: [], extra: [[\"17:45–18:30\",\"התעמלות קרקע\"]] } },\n  { daniel: { end: \"11:40\", tzaharon: null,\n      school: [[\"08:00–08:50\",\"תלמיד מלמד\"],[\"08:50–09:35\",\"מתמטיקה\"],[\"10:10–10:55\",\"תנ״ך\"],[\"10:55–11:40\",\"כישורי חיים\"]],\n      tzchug: [], extra: [] },\n    naya: { end: \"11:40\", tzaharon: null,\n      school: [[\"08:00–08:50\",\"תלמיד מלמד\"],[\"08:50–09:35\",\"חשבון\"],[\"10:10–10:55\",\"מפתח הלב\"],[\"10:55–11:40\",\"בעקבות סיפורים\"]],\n      tzchug: [], extra: [] } },\n]};\n\nlet activeTab = \"homework\";\nlet schedDay = (() => { const d = new Date().getDay(); return (d >= 0 && d <= 5) ? d : 0; })();\n\nfunction rangeMinutes(t){\n  const m = t.match(/^(\\d{1,2}):(\\d{2})–(\\d{1,2}):(\\d{2})$/);\n  if(!m) return null;\n  return [+m[1] * 60 + +m[2], +m[3] * 60 + +m[4]];\n}\n\nfunction fmtMin(m){\n  return String(Math.floor(m / 60)).padStart(2, \"0\") + \":\" + String(m % 60).padStart(2, \"0\");\n}\n\nfunction srow(time, title, tagCls, tagLabel, isNow){\n  return '<div class=\"srow' + (isNow ? \" now\" : \"\") + '\"><span class=\"stime\">' + esc(time)\n    + '</span><span class=\"stitle\">' + esc(title) + \"</span>\"\n    + (isNow ? '<span class=\"nowtag\">עכשיו</span>' : \"\")\n    + '<span class=\"stag ' + tagCls + '\">' + tagLabel + \"</span></div>\";\n}\n\nfunction renderSchedule(){\n  const today = new Date().getDay();\n  const nowMin = new Date().getHours() * 60 + new Date().getMinutes();\n  const isToday = schedDay === today;\n  const chips = document.getElementById(\"dayChips\");\n  chips.innerHTML = [0,1,2,3,4,5].map(d =>\n    '<button class=\"dchip' + (d === schedDay ? \" on\" : \"\") + (d === today ? \" today\" : \"\")\n    + '\" data-day=\"' + d + '\">' + HEB_DAYS[d] + (d === today ? \" · היום\" : \"\") + \"</button>\").join(\"\");\n  chips.querySelectorAll(\".dchip\").forEach(b => b.addEventListener(\"click\", () => {\n    schedDay = +b.dataset.day;\n    try{ history.replaceState(null, \"\", \"#schedule\" + (schedDay !== new Date().getDay() ? \"-\" + schedDay : \"\")); }catch(e){}\n    renderSchedule();\n  }));\n\n  const day = SCHEDULE.days[schedDay];\n  const isNow = t => {\n    if(!isToday) return false;\n    const r = rangeMinutes(t);\n    return r && nowMin >= r[0] && nowMin < r[1];\n  };\n  let html = '<div class=\"sched-day\">יום ' + HEB_DAYS[schedDay]\n    + (isToday ? '<span class=\"today-tag\">היום</span>' : \"\") + \"</div>\";\n  for(const k of [\"daniel\",\"naya\"]){\n    const kid = KIDS[k];\n    const d = day[k];\n    html += '<section class=\"child\"><div class=\"child-head\"><span class=\"dot ' + kid.cls\n      + '\"></span><h2>' + kid.emoji + \" \" + kid.name + \"</h2></div>\";\n    // School lessons, with a break box wherever the gap between two\n    // consecutive lessons is over 5 minutes (e.g. 09:35–10:10, 11:40–12:00).\n    let prevEnd = null;\n    for(const [time, title] of d.school){\n      const r = rangeMinutes(time);\n      if(r && prevEnd !== null && r[0] - prevEnd > 5){\n        const gap = r[0] - prevEnd;\n        const brkTime = fmtMin(prevEnd) + \"–\" + fmtMin(r[0]);\n        const brkNow = isToday && nowMin >= prevEnd && nowMin < r[0];\n        html += '<div class=\"srow brk' + (brkNow ? \" now\" : \"\") + '\"><span class=\"stime\">' + esc(brkTime)\n          + '</span><span class=\"stitle\">☕ הפסקה · ' + gap + ' דקות</span>'\n          + (brkNow ? '<span class=\"nowtag\">עכשיו</span>' : \"\")\n          + '<span class=\"stag brk\">הפסקה</span></div>';\n      }\n      html += srow(time, title, \"school\", \"בית ספר\", isNow(time));\n      if(r) prevEnd = r[1];\n    }\n    html += '<div class=\"srow\"><span class=\"stime\">' + esc(d.end)\n      + '</span><span class=\"stitle\">🏫 סיום בית ספר</span><span class=\"stag end\">סיום</span></div>';\n    if(d.tzaharon){\n      html += '<div class=\"srow tzbar\"><span class=\"stime\">' + esc(d.tzaharon)\n        + '</span><span class=\"stitle\">צהרון</span><span class=\"stag tzaharon\">צהרון</span></div>';\n      for(const [time, title] of d.tzchug) html += srow(time, title, \"chug\", \"חוג צהרון\", isNow(time));\n    }\n    for(const [time, title] of (d.extra || [])) html += srow(time, title, \"chug\", \"חוג\", isNow(time));\n    html += \"</section>\";\n  }\n  document.getElementById(\"schedApp\").innerHTML = html;\n}\n\nfunction switchTab(tab){\n  activeTab = tab;\n  document.querySelectorAll(\".tab\").forEach(b => b.classList.toggle(\"on\", b.dataset.tab === tab));\n  document.getElementById(\"homeworkView\").style.display = tab === \"homework\" ? \"block\" : \"none\";\n  document.getElementById(\"scheduleView\").style.display = tab === \"schedule\" ? \"block\" : \"none\";\n  document.getElementById(\"remindersView\").style.display = tab === \"reminders\" ? \"block\" : \"none\";\n  if(tab === \"schedule\") renderSchedule();\n  if(tab === \"reminders\") renderReminders();\n  try{\n    const h = tab === \"homework\" ? \"#homework\"\n      : tab === \"reminders\" ? \"#reminders\"\n      : \"#schedule\" + (schedDay !== new Date().getDay() ? \"-\" + schedDay : \"\");\n    history.replaceState(null, \"\", h);\n  }catch(e){}\n}\n\n/* ---- reminders tab ---- */\nfunction remSort(list){\n  return list.slice().sort((a, b) => {\n    if(a.done !== b.done) return a.done ? 1 : -1;\n    const ta = a.time || \"99:99\", tb = b.time || \"99:99\";\n    if(ta !== tb) return ta < tb ? -1 : 1;\n    return (a.created || \"\") < (b.created || \"\") ? -1 : 1;\n  });\n}\n\nfunction remRow(r){\n  const kid = r.child && KIDS[r.child] ? KIDS[r.child].emoji + \" \" + KIDS[r.child].name : \"שני הילדים\";\n  const meta = [r.time ? \"🕐 \" + esc(r.time) : \"\", kid].filter(Boolean).join(\" · \");\n  return '<div class=\"rem-row' + (r.done ? \" done\" : \"\") + '\">'\n    + '<input type=\"checkbox\" class=\"rem-check\" data-id=\"' + esc(r.id) + '\"' + (r.done ? \" checked\" : \"\") + '>'\n    + '<div class=\"rem-main\"><div class=\"rem-text\">' + esc(r.text) + \"</div>\"\n    + (meta ? '<div class=\"rem-meta\">' + meta + \"</div>\" : \"\") + \"</div>\"\n    + '<button class=\"rem-del\" data-id=\"' + esc(r.id) + '\" aria-label=\"מחק תזכורת\">✕</button></div>';\n}\n\nfunction renderReminders(){\n  if(!remDate) remDate = todayISO();\n  const dateInput = document.getElementById(\"remDate\");\n  if(dateInput && dateInput.value !== remDate) dateInput.value = remDate;\n  const isToday = remDate === todayISO();\n  const d = new Date(remDate + \"T12:00:00\");\n  const dayLabel = isToday ? \"היום\" : \"יום \" + HEB_DAYS[d.getDay()];\n  let html = '<div class=\"sched-day\">' + dayLabel + \" · \" + shortDate(remDate)\n    + (isToday ? '<span class=\"today-tag\">היום</span>' : \"\") + \"</div>\";\n\n  // Overdue undone reminders (only when looking at today).\n  const overdue = isToday ? REMINDERS.filter(r => !r.done && r.date < remDate) : [];\n  if(overdue.length){\n    html += '<div class=\"rem-sec\">⏰ שעבר זמנן</div>';\n    html += remSort(overdue).map(remRow).join(\"\");\n  }\n\n  const list = REMINDERS.filter(r => r.date === remDate);\n  html += '<div class=\"rem-sec\">🔔 תזכורות ליום הזה</div>';\n  html += list.length ? remSort(list).map(remRow).join(\"\")\n    : '<div class=\"rem-empty\">אין תזכורות ליום הזה — הוסיפו אחת למעלה 🙂</div>';\n\n  // Homework tasks due on this day (from the sheet, read-only here).\n  const due = DATA.tasks.filter(t => t.due_iso === remDate && !t.done);\n  if(due.length){\n    html += '<div class=\"rem-sec\">📚 מטלות שצריכות להסתיים ' + (isToday ? \"היום\" : \"ביום הזה\") + \"</div>\";\n    html += due.map(t => {\n      const kid = KIDS[t.child] || {};\n      return '<div class=\"rem-row\"><div class=\"rem-main\"><div class=\"rem-text\">' + esc(t.short || t.title) + \"</div>\"\n        + '<div class=\"rem-meta\">' + (kid.emoji || \"\") + \" \" + (kid.name || \"\") + (t.subject ? \" · \" + esc(t.subject) : \"\") + \"</div></div></div>\";\n    }).join(\"\");\n  }\n  document.getElementById(\"remApp\").innerHTML = html;\n\n  document.querySelectorAll(\"#remApp .rem-check\").forEach(cb => {\n    cb.addEventListener(\"change\", async () => {\n      const id = cb.dataset.id, done = cb.checked;\n      cb.closest(\".rem-row\").classList.toggle(\"done\", done);\n      try{\n        await fetchJSON(\"/api/reminders/\" + encodeURIComponent(id) + \"/done\", {\n          method: \"POST\", headers: {\"Content-Type\":\"application/json\"},\n          body: JSON.stringify({done})\n        }, 3);\n        const r = REMINDERS.find(x => x.id === id);\n        if(r) r.done = done;\n        renderReminders();\n      }catch(e){\n        cb.checked = !done;\n        cb.closest(\".rem-row\").classList.toggle(\"done\", !done);\n        alert(\"הסימון לא נשמר — נסו שוב.\");\n      }\n    });\n  });\n  document.querySelectorAll(\"#remApp .rem-del\").forEach(btn => {\n    btn.addEventListener(\"click\", async () => {\n      const id = btn.dataset.id;\n      if(!confirm(\"למחוק את התזכורת?\")) return;\n      try{\n        await fetchJSON(\"/api/reminders/\" + encodeURIComponent(id), {method: \"DELETE\"}, 3);\n        REMINDERS = REMINDERS.filter(x => x.id !== id);\n        renderReminders();\n      }catch(e){ alert(\"המחיקה נכשלה — נסו שוב.\"); }\n    });\n  });\n}\n\nasync function loadReminders(){\n  try{\n    const data = await fetchJSON(\"/api/reminders\", null, 3);\n    REMINDERS = data.reminders || [];\n    if(activeTab === \"reminders\") renderReminders();\n  }catch(e){ /* reminders stay as-is; the tab shows the empty state */ }\n}\n\nasync function addReminder(){\n  const textEl = document.getElementById(\"remText\");\n  const text = (textEl.value || \"\").trim();\n  if(!text){ textEl.focus(); return; }\n  const btn = document.getElementById(\"remAdd\");\n  btn.disabled = true;\n  try{\n    const created = await fetchJSON(\"/api/reminders\", {\n      method: \"POST\", headers: {\"Content-Type\":\"application/json\"},\n      body: JSON.stringify({\n        text,\n        date: remDate || todayISO(),\n        time: document.getElementById(\"remTime\").value || \"\",\n        child: document.getElementById(\"remChild\").value || \"all\"\n      })\n    }, 3);\n    if(created.reminder) REMINDERS.push(created.reminder);\n    textEl.value = \"\";\n    document.getElementById(\"remTime\").value = \"\";\n    renderReminders();\n  }catch(e){ alert(\"התזכורת לא נשמרה — נסו שוב.\"); }\n  btn.disabled = false;\n}\n\n/* ---- sync: reload the site's data from the server ---- */\nfunction setSyncStatus(msg){ document.getElementById(\"syncStatus\").textContent = msg; }\n\nasync function syncNow(){\n  const btn = document.getElementById(\"syncBtn\");\n  btn.disabled = true;\n  btn.textContent = \"מסנכרן…\";\n  try{\n    WEEKS = await fetchJSON(\"/api/weeks\");\n    if(viewWeek) await loadWeek(viewWeek);\n    else { DATA = await fetchJSON(\"/api/tasks\"); render(); }\n    await loadReminders();\n    lastLoadAt = Date.now();\n    const now = new Date();\n    setSyncStatus(\"✅ סונכרן \" + String(now.getHours()).padStart(2, \"0\") + \":\" + String(now.getMinutes()).padStart(2, \"0\")\n      + (DATA.updated ? \" · נתוני הגיליון מ־\" + formatUpdated(DATA.updated) : \"\"));\n  }catch(e){\n    setSyncStatus(\"⚠️ הסנכרון נכשל — נסו שוב\");\n  }\n  btn.textContent = \"🔄 סנכרן\";\n  btn.disabled = false;\n}\n\nconst esc = s => String(s ?? \"\").replace(/[&<>\"']/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst isoOf = d => d.getFullYear() + \"-\" + String(d.getMonth()+1).padStart(2,\"0\") + \"-\" + String(d.getDate()).padStart(2,\"0\");\nconst todayISO = () => isoOf(new Date());\nconst tomorrowISO = () => { const d = new Date(); d.setDate(d.getDate()+1); return isoOf(d); };\nconst HEB_DAYS = [\"ראשון\",\"שני\",\"שלישי\",\"רביעי\",\"חמישי\",\"שישי\",\"שבת\"];\n\nfunction dayName(iso){\n  const m = iso.match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);\n  if(!m) return \"\";\n  return HEB_DAYS[new Date(+m[1], +m[2]-1, +m[3]).getDay()];\n}\nfunction shortDate(iso){\n  const m = iso.match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);\n  return m ? (+m[3]) + \"/\" + (+m[2]) : \"\";\n}\n\nfunction formatUpdated(u){\n  if(!u) return \"\";\n  const dateOnly = u.match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);\n  if(dateOnly) return (+dateOnly[3]) + \"/\" + (+dateOnly[2]) + \"/\" + dateOnly[1];\n  const d = new Date(u);\n  if(isNaN(d)) return u;\n  const hh = String(d.getHours()).padStart(2,\"0\");\n  const mm = String(d.getMinutes()).padStart(2,\"0\");\n  return d.getDate() + \"/\" + (d.getMonth()+1) + \"/\" + d.getFullYear() + \", \" + hh + \":\" + mm;\n}\n\nfunction duePill(t){\n  if(t.done) return '<span class=\"duepill\">✅ בוצע</span>';\n  if(!t.due_iso){\n    if(t.due && t.due !== \"לא צוין\") return '<span class=\"duepill\">' + esc(t.due) + \"</span>\";\n    return '<span class=\"duepill\">ללא תאריך</span>';\n  }\n  if(t.due_iso === todayISO()) return '<span class=\"duepill today\">להיום · ' + shortDate(t.due_iso) + \"</span>\";\n  if(t.due_iso === tomorrowISO()) return '<span class=\"duepill tomorrow\">למחר · ' + shortDate(t.due_iso) + \"</span>\";\n  if(t.due_iso < todayISO()) return '<span class=\"duepill overdue\">באיחור · ' + shortDate(t.due_iso) + \"</span>\";\n  return '<span class=\"duepill future\">עד ' + dayName(t.due_iso) + \" \" + shortDate(t.due_iso) + \"</span>\";\n}\n\nfunction givenPill(t){\n  if(!t.given_iso) return \"\";\n  return '<span class=\"duepill given\">ניתנה ' + shortDate(t.given_iso) + \"</span>\";\n}\n\nfunction weekShort(w){ return w.replace(/^שבוע\\s*/, \"\"); }\n\nfunction renderWeekNav(){\n  const nav = document.getElementById(\"weeknav\");\n  if(!WEEKS.weeks.length){ nav.style.display = \"none\"; return; }\n  nav.style.display = \"block\";\n  const idx = WEEKS.weeks.indexOf(viewWeek);\n  const isCurrent = viewWeek === WEEKS.current;\n  document.getElementById(\"weekName\").textContent = viewWeek;\n  const tag = document.getElementById(\"weekTag\");\n  tag.textContent = isCurrent ? \"השבוע\" : \"שבוע קודם\";\n  tag.className = \"wtag\" + (isCurrent ? \"\" : \" old\");\n  document.getElementById(\"prevWeek\").disabled = idx <= 0;\n  document.getElementById(\"nextWeek\").disabled = idx < 0 || idx >= WEEKS.weeks.length - 1;\n\n  const chips = document.getElementById(\"weekChips\");\n  chips.innerHTML = WEEKS.weeks.map(w =>\n    '<button class=\"wchip' + (w === viewWeek ? \" on\" : \"\") + '\" data-week=\"' + esc(w) + '\">'\n    + esc(weekShort(w)) + (w === WEEKS.current ? \" · השבוע\" : \"\") + \"</button>\").join(\"\");\n  chips.querySelectorAll(\".wchip\").forEach(b => {\n    b.addEventListener(\"click\", () => loadWeek(b.dataset.week));\n  });\n\n  const total = DATA.tasks.length;\n  const nw = DATA.tasks.filter(t => t.is_new).length;\n  const nc = DATA.tasks.filter(t => t.carried).length;\n  const nd = DATA.tasks.filter(t => t.done).length;\n  document.getElementById(\"weekStats\").innerHTML =\n    (total ? \"<span><b>\" + total + \"</b> משימות</span>\" : \"\")\n    + (nw ? '<span class=\"st-new\">✨ ' + nw + \" חדשות</span>\" : \"\")\n    + (nc ? '<span class=\"st-carried\">🔁 ' + nc + \" נגררו משבוע שעבר</span>\" : \"\")\n    + \"<span>✅ <b>\" + nd + \"</b> בוצעו</span>\";\n}\n\nfunction sortTasks(list){\n  // Open first, by due date (earliest first, no date last); done last,\n  // also by due date. Stable for equal keys (sheet order kept).\n  return list.slice().sort((a, b) => {\n    if(a.done !== b.done) return a.done ? 1 : -1;\n    const da = a.due_iso || \"9999-99-99\";\n    const db = b.due_iso || \"9999-99-99\";\n    if(da !== db) return da < db ? -1 : 1;\n    return 0;\n  });\n}\n\nfunction render(){\n  renderWeekNav();\n  const lu = document.getElementById(\"lastUpdated\");\n  lu.textContent = DATA.updated ? \"🕐 עדכון אחרון: \" + formatUpdated(DATA.updated) : \"\";\n  if(DATA.updated) setSyncStatus(\"נתוני הגיליון עודכנו: \" + formatUpdated(DATA.updated));\n  const sp = document.getElementById(\"sourcePulls\");\n  const parts = [];\n  if(DATA.last_whatsapp) parts.push(\"נשלף מוואטסאפ: \" + formatUpdated(DATA.last_whatsapp));\n  if(DATA.last_webtop) parts.push(\"נשלף מוובטופ: \" + formatUpdated(DATA.last_webtop));\n  sp.textContent = parts.join(\" · \");\n  const app = document.getElementById(\"app\");\n  const kids = [\"daniel\",\"naya\"].filter(k => childFilter === \"all\" || childFilter === k);\n  let html = \"\";\n  let totalOpen = 0, totalDone = 0;\n\n  for(const k of kids){\n    const all = DATA.tasks.filter(t => t.child === k);\n    const done = all.filter(t => t.done).length;\n    totalOpen += all.length - done; totalDone += done;\n    let list = all;\n    if(statusFilter === \"open\") list = all.filter(t => !t.done);\n    if(statusFilter === \"done\") list = all.filter(t => t.done);\n    list = sortTasks(list);\n    const pct = all.length ? Math.round(done / all.length * 100) : 0;\n    const kid = KIDS[k];\n\n    html += '<section class=\"child\">';\n    html += '<div class=\"child-head\"><span class=\"dot ' + kid.cls + '\"></span><h2>' + kid.emoji + \" \" + kid.name + \"</h2>\"\n      + '<span class=\"count\">' + done + \" מתוך \" + all.length + \" בוצעו</span></div>\";\n    html += '<div class=\"bar ' + kid.cls + '\"><div style=\"width:' + pct + '%\"></div></div>';\n\n    if(!list.length){\n      html += '<div class=\"empty\">' + (statusFilter === \"done\" ? \"עוד לא סומן שום דבר כבוצע\" : \"אין משימות פתוחות — כל הכבוד! 🎉\") + \"</div>\";\n    }\n    for(const t of list){\n      const shortTitle = t.short || t.title;\n      const detailsText = (t.details || \"\").trim();\n      html += '<div class=\"card' + (t.done ? \" done\" : \"\") + '\">'\n        + '<div class=\"card-top\">'\n        + '<input type=\"checkbox\" class=\"check\" data-id=\"' + esc(t.id) + '\"' + (t.done ? \" checked\" : \"\") + '>'\n        + '<div class=\"card-main\">'\n        + '<div class=\"title-row\"><div class=\"title\">' + esc(shortTitle) + \"</div>\" + duePill(t) + givenPill(t) + \"</div>\"\n        + '<div class=\"tags\">'\n        + (t.subject ? '<span class=\"tag\">' + esc(t.subject) + \"</span>\" : \"\")\n        + (t.kind ? '<span class=\"tag\">' + esc(t.kind) + \"</span>\" : \"\")\n        + (t.carried ? '<span class=\"tag carried\">🔁 נגרר משבוע שעבר</span>' : \"\")\n        + (t.is_new ? '<span class=\"tag isnew\">✨ חדש השבוע</span>' : \"\")\n        + \"</div>\"\n        + \"</div></div>\"\n        + '<button class=\"details-btn\" data-id=\"' + esc(t.id) + '\">פירוט ▾</button>'\n        + '<div class=\"details\" id=\"det-' + esc(t.id) + '\">'\n        + (detailsText ? '<div class=\"details-text\">' + esc(detailsText) + \"</div>\" : \"\")\n        + '<div class=\"details-meta\">' + [t.due ? \"מועד: \" + esc(t.due) : \"\", t.source ? \"מקור: \" + esc(t.source) : \"\"].filter(Boolean).join(\" · \") + \"</div>\";\n      if(t.links && t.links.length){\n        html += '<div class=\"links\">' + t.links.map(l =>\n          '<a href=\"' + esc(l.url) + '\" target=\"_blank\" rel=\"noopener\">' + esc(l.label) + \"</a>\").join(\"\") + \"</div>\";\n      }\n      html += \"</div></div>\";\n    }\n    html += \"</section>\";\n  }\n  if(childFilter === \"all\" && totalOpen === 0 && totalDone > 0){\n    html += '<div class=\"alldone\">🎉 כל המשימות של השבוע בוצעו!</div>';\n  }\n  app.innerHTML = html;\n\n  app.querySelectorAll(\".check\").forEach(cb => {\n    cb.addEventListener(\"change\", async () => {\n      const id = cb.dataset.id;\n      const done = cb.checked;\n      const card = cb.closest(\".card\");\n      card.classList.toggle(\"done\", done);\n      try{\n        await fetchJSON(\"/api/tasks/\" + encodeURIComponent(id) + \"/done?week=\" + encodeURIComponent(viewWeek), {\n          method: \"POST\", headers: {\"Content-Type\":\"application/json\"},\n          body: JSON.stringify({done})\n        }, 5);\n        const t = DATA.tasks.find(x => x.id === id);\n        if(t) t.done = done;\n        render();\n      }catch(e){\n        cb.checked = !done;\n        card.classList.toggle(\"done\", !done);\n        alert(\"הסימון לא נשמר — נסו שוב.\");\n      }\n    });\n  });\n\n  app.querySelectorAll(\".details-btn\").forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      const det = document.getElementById(\"det-\" + btn.dataset.id);\n      const open = det.classList.toggle(\"open\");\n      btn.textContent = open ? \"פירוט ▴\" : \"פירוט ▾\";\n    });\n  });\n}\n\nasync function fetchJSON(url, opts, attempts){\n  attempts = attempts || 6;\n  let delay = 300;\n  for(let i = 0; i < attempts; i++){\n    try{\n      const r = await fetch(url, opts);\n      if(!r.ok) throw new Error(\"http \" + r.status);\n      return await r.json();\n    }catch(e){\n      if(i === attempts - 1) throw e;\n      await new Promise(res => setTimeout(res, delay));\n      delay = Math.min(delay * 2, 3000);\n    }\n  }\n}\n\nasync function loadWeek(week){\n  try{\n    DATA = await fetchJSON(\"/api/tasks?week=\" + encodeURIComponent(week));\n    viewWeek = DATA.week || week;\n    document.getElementById(\"err\").style.display = \"none\";\n    render();\n  }catch(e){\n    document.getElementById(\"err\").style.display = \"block\";\n  }\n}\n\nasync function load(){\n  try{\n    WEEKS = await fetchJSON(\"/api/weeks\");\n    viewWeek = WEEKS.current || \"\";\n    if(viewWeek) await loadWeek(viewWeek);\n    else { DATA = await fetchJSON(\"/api/tasks\"); render(); }\n    lastLoadAt = Date.now();\n    await loadReminders();\n  }catch(e){\n    document.getElementById(\"err\").style.display = \"block\";\n  }\n}\n\ndocument.querySelectorAll(\".tab\").forEach(b => {\n  b.addEventListener(\"click\", () => switchTab(b.dataset.tab));\n});\ndocument.getElementById(\"prevWeek\").addEventListener(\"click\", () => {\n  const idx = WEEKS.weeks.indexOf(viewWeek);\n  if(idx > 0) loadWeek(WEEKS.weeks[idx - 1]);\n});\ndocument.getElementById(\"nextWeek\").addEventListener(\"click\", () => {\n  const idx = WEEKS.weeks.indexOf(viewWeek);\n  if(idx >= 0 && idx < WEEKS.weeks.length - 1) loadWeek(WEEKS.weeks[idx + 1]);\n});\ndocument.querySelectorAll(\"#statusFilters .chip\").forEach(b => {\n  b.addEventListener(\"click\", () => {\n    document.querySelectorAll(\"#statusFilters .chip\").forEach(x => x.classList.remove(\"on\"));\n    b.classList.add(\"on\");\n    statusFilter = b.dataset.status;\n    render();\n  });\n});\ndocument.querySelectorAll(\"#childFilters .chip\").forEach(b => {\n  b.addEventListener(\"click\", () => {\n    document.querySelectorAll(\"#childFilters .chip\").forEach(x => x.classList.remove(\"on\"));\n    b.classList.add(\"on\");\n    childFilter = b.dataset.child;\n    render();\n  });\n});\n\ndocument.getElementById(\"syncBtn\").addEventListener(\"click\", syncNow);\ndocument.addEventListener(\"visibilitychange\", () => {\n  // Coming back to the app after a while: refresh silently.\n  if(!document.hidden && lastLoadAt && Date.now() - lastLoadAt > 5 * 60 * 1000) syncNow();\n});\n\ndocument.getElementById(\"remDate\").addEventListener(\"change\", (e) => {\n  remDate = e.target.value || todayISO();\n  renderReminders();\n});\ndocument.getElementById(\"remToday\").addEventListener(\"click\", () => {\n  remDate = todayISO();\n  renderReminders();\n});\ndocument.getElementById(\"remAdd\").addEventListener(\"click\", addReminder);\ndocument.getElementById(\"remText\").addEventListener(\"keydown\", (e) => {\n  if(e.key === \"Enter\") addReminder();\n});\n\ndocument.getElementById(\"shareSched\").addEventListener(\"click\", async () => {\n  const btn = document.getElementById(\"shareSched\");\n  const url = location.origin + location.pathname + \"#schedule-\" + schedDay;\n  try{\n    await navigator.clipboard.writeText(url);\n    btn.textContent = \"✅ הקישור הועתק\";\n  }catch(e){\n    window.prompt(\"העתיקו את הקישור:\", url);\n    return;\n  }\n  setTimeout(() => { btn.textContent = \"🔗 העתק קישור ליום הזה\"; }, 2500);\n});\n\n(function initTabFromHash(){\n  const h = (location.hash || \"\").replace(/^#/, \"\");\n  if(h === \"homework\"){ switchTab(\"homework\"); return; }\n  if(h === \"schedule\"){ switchTab(\"schedule\"); return; }\n  if(h === \"reminders\"){ switchTab(\"reminders\"); return; }\n  const m = h.match(/^schedule-([0-5])$/);\n  if(m){ schedDay = +m[1]; switchTab(\"schedule\"); }\n})();\n\nload();\n</script>\n</body>\n</html>\n";

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8' },
  });
}

const weekKey = (week) => 'week:' + week;

function weekOrder(week) {
  const m = String(week).match(/(\d{1,2})[–\-](\d{1,2})\.(\d{1,2})/);
  if (!m) return 0;
  const d1 = parseInt(m[1], 10);
  const mo = parseInt(m[3], 10);
  const y = mo >= 9 ? 2026 : 2027;
  return y * 10000 + mo * 100 + d1;
}

async function getMeta(env) {
  const meta = await env.HOMEWORK_KV.get('meta', 'json');
  return meta || { weeks: [], current: '' };
}

async function getWeek(env, week) {
  const doc = await env.HOMEWORK_KV.get(weekKey(week), 'json');
  return doc || { week, updated: '', tasks: [] };
}

async function getCurrentDoc(env) {
  const meta = await getMeta(env);
  if (meta.current) return getWeek(env, meta.current);
  const legacy = await env.HOMEWORK_KV.get('state', 'json');
  return legacy || { week: '', updated: '', tasks: [] };
}

function findTask(doc, child, title) {
  if (!doc) return null;
  return doc.tasks.find((t) => t.child === child && t.title === title) || null;
}

// ---- shared reminders (KV key "reminders", one array, max 200) ----
async function getReminders(env) {
  return (await env.HOMEWORK_KV.get('reminders', 'json')) || [];
}
async function putReminders(env, list) {
  await env.HOMEWORK_KV.put('reminders', JSON.stringify(list.slice(-200)));
}
function reminderId() {
  return 'r-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (path === '/' || path === '/index.html') {
      return new Response(HTML, { headers: { 'content-type': 'text/html; charset=utf-8' } });
    }
    if (path === '/health') return json({ ok: true });

    if (path === '/api/weeks' && request.method === 'GET') {
      return json(await getMeta(env));
    }

    if (path === '/api/tasks' && request.method === 'GET') {
      const week = url.searchParams.get('week');
      return json(week ? await getWeek(env, week) : await getCurrentDoc(env));
    }

    const doneMatch = path.match(/^\/api\/tasks\/([^/]+)\/done$/);
    if (doneMatch && request.method === 'POST') {
      const id = decodeURIComponent(doneMatch[1]);
      const week = url.searchParams.get('week');
      let body = {};
      try { body = await request.json(); } catch { /* ignore */ }
      const doc = week ? await getWeek(env, week) : await getCurrentDoc(env);
      if (!doc.week) return json({ error: 'no such week' }, 404);
      const task = doc.tasks.find((t) => t.id === id);
      if (!task) return json({ error: 'not found' }, 404);
      task.done = !!body.done;
      await env.HOMEWORK_KV.put(weekKey(doc.week), JSON.stringify(doc));
      return json(task);
    }

    // ---- reminders ----
    if (path === '/api/reminders' && request.method === 'GET') {
      return json({ reminders: await getReminders(env) });
    }
    if (path === '/api/reminders' && request.method === 'POST') {
      let body = {};
      try { body = await request.json(); } catch { /* ignore */ }
      const text = String(body.text || '').trim().slice(0, 200);
      const date = String(body.date || '');
      if (!text || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
        return json({ error: 'text and date (YYYY-MM-DD) are required' }, 400);
      }
      const time = /^\d{2}:\d{2}$/.test(String(body.time || '')) ? body.time : '';
      const child = ['all', 'daniel', 'naya'].includes(body.child) ? body.child : 'all';
      const reminder = {
        id: reminderId(), text, date, time, child, done: false,
        created: new Date().toISOString(),
      };
      const list = await getReminders(env);
      list.push(reminder);
      await putReminders(env, list);
      return json({ reminder }, 201);
    }
    const remDoneMatch = path.match(/^\/api\/reminders\/([^/]+)\/done$/);
    if (remDoneMatch && request.method === 'POST') {
      const id = decodeURIComponent(remDoneMatch[1]);
      let body = {};
      try { body = await request.json(); } catch { /* ignore */ }
      const list = await getReminders(env);
      const r = list.find((x) => x.id === id);
      if (!r) return json({ error: 'not found' }, 404);
      r.done = !!body.done;
      await putReminders(env, list);
      return json(r);
    }
    const remDelMatch = path.match(/^\/api\/reminders\/([^/]+)$/);
    if (remDelMatch && request.method === 'DELETE') {
      const id = decodeURIComponent(remDelMatch[1]);
      const list = await getReminders(env);
      const kept = list.filter((x) => x.id !== id);
      if (kept.length === list.length) return json({ error: 'not found' }, 404);
      await putReminders(env, kept);
      return json({ ok: true });
    }

    if (path === '/api/sync' && request.method === 'POST') {
      const auth = request.headers.get('Authorization') || '';
      if (auth !== 'Bearer ' + env.SYNC_SECRET) {
        return new Response('unauthorized', { status: 401 });
      }
      const data = await request.json();
      const week = data.week;
      const meta = await getMeta(env);
      const legacy = await env.HOMEWORK_KV.get('state', 'json');

      // Same-week doc (for done + flag preservation on re-sync).
      let sameDoc = await env.HOMEWORK_KV.get(weekKey(week), 'json');
      if (!sameDoc && legacy && legacy.week === week) sameDoc = legacy;

      // Previous-week doc (for carried/new computation): the latest stored
      // week strictly earlier than this one; the legacy doc counts if it is
      // earlier and no stored week is.
      let prevDoc = null;
      const earlier = meta.weeks.filter((w) => weekOrder(w) < weekOrder(week));
      if (earlier.length) {
        earlier.sort((a, b) => weekOrder(a) - weekOrder(b));
        prevDoc = await getWeek(env, earlier[earlier.length - 1]);
      } else if (legacy && weekOrder(legacy.week) < weekOrder(week)) {
        prevDoc = legacy;
      }

      let carried = 0;
      let isNew = 0;
      const tasks = (data.tasks || []).map((t) => {
        const same = findTask(sameDoc, t.child, t.title);
        const prev = findTask(prevDoc, t.child, t.title);
        const c = same ? !!(same.carried ?? !!prev) : !!prev;
        const n = same ? !!(same.is_new ?? !c) : !c;
        const done = !!(t.done || (same && same.done) || (c && prev && prev.done));
        if (c) carried += 1; else isNew += 1;
        return { ...t, carried: c, is_new: n, done };
      });

      const doc = {
        week,
        updated: data.updated || '',
        last_whatsapp: data.last_whatsapp || (sameDoc && sameDoc.last_whatsapp) || '',
        last_webtop: data.last_webtop || (sameDoc && sameDoc.last_webtop) || '',
        tasks,
      };
      await env.HOMEWORK_KV.put(weekKey(week), JSON.stringify(doc));
      if (!meta.weeks.includes(week)) meta.weeks.push(week);
      meta.weeks.sort((a, b) => weekOrder(a) - weekOrder(b));
      meta.current = week;
      await env.HOMEWORK_KV.put('meta', JSON.stringify(meta));
      if (legacy && legacy.week === week) {
        await env.HOMEWORK_KV.delete('state');
      }
      return json({ ok: true, count: tasks.length, week, carried, new: isNew });
    }

    return new Response('Not found', { status: 404 });
  },
};
